//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn shared_normalize_canonical_binding_inert_owners_aliases_and_cdata_barriers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var d=Object.getOwnPropertyDescriptor(Node.prototype,'normalize');if(!d||d.value.name!=='normalize'||d.value.length!==0||!d.enumerable||!d.writable||!d.configurable)throw 'canonical Node normalize binding';var xml=document.implementation.createDocument(null,''),generic=new Document(),html=document.implementation.createHTMLDocument('owner'),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;for(var owner of [document,html,xml,generic,template]){var parent=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),empty=owner.createTextNode(''),a=owner.createTextNode('A\ud83d'),middle=owner.createTextNode(''),b=owner.createTextNode('\ude00B'),stop=owner===xml||owner===generic||owner===template?owner.createCDATASection('C'):owner.createComment('C'),tail=owner.createTextNode('D');for(var node of [empty,a,middle,b,stop,tail])parent.appendChild(node);var list=parent.childNodes,binding={held:a};a.bindingState=binding;empty.normalize();a.normalize();if(parent.firstChild!==empty||a.data!=='A\ud83d')throw 'receiver itself excluded';var calls=0;if(parent.normalize({toString:function(){calls++;throw 'ignored';}})!==undefined||calls)throw 'ignored args';if(parent.childNodes!==list||list.length!==3||list[0]!==a||list[1]!==stop||list[2]!==tail||a.data!=='A\ud83d\ude00B'||a.ownerDocument!==owner||a.bindingState!==binding||b.data!=='\ude00B'||empty.data!==''||middle.data!==''||b.parentNode!==null||empty.parentNode!==null||middle.parentNode!==null||stop.data!=='C'||tail.data!=='D')throw 'native shared normalization preserves aliases values owners and barriers';}
"#);
}
#[test]
fn shared_normalize_mutation_records_follow_native_tree_order_and_keep_singleton_records(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var root=document.createElement('div'),a=document.createTextNode('left'),b=document.createTextNode('right'),nested=document.createElement('span'),solo=document.createTextNode('solo'),last=document.createTextNode('last');root.appendChild(a);root.appendChild(b);nested.appendChild(solo);root.appendChild(nested);root.appendChild(last);var watch=new MutationObserver(function(){});watch.observe(root,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});root.normalize();var records=watch.takeRecords();if(records.length!==4||records[0].type!=='characterData'||records[0].target!==a||records[0].oldValue!=='left'||records[1].type!=='childList'||records[1].target!==root||records[1].removedNodes[0]!==b||records[1].previousSibling!==a||records[1].nextSibling!==nested||records[2].type!=='characterData'||records[2].target!==solo||records[2].oldValue!=='solo'||records[3].type!=='characterData'||records[3].target!==last||records[3].oldValue!=='last'||a.data!=='leftright'||b.data!=='right')throw 'normalize observations in descendant tree order including singleton no-op';");
}
#[test]
fn shared_normalize_template_dedicated_content_is_not_ordinary_host_descendants(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var owner=document.implementation.createHTMLDocument('owner'),host=owner.createElement('template'),content=host.content,a=content.ownerDocument.createTextNode('A'),b=content.ownerDocument.createTextNode('B');content.appendChild(a);content.appendChild(b);var ordinary=owner.createTextNode('host'),empty=owner.createTextNode('');host.appendChild(ordinary);host.appendChild(empty);host.normalize();if(host.firstChild!==ordinary||host.childNodes.length!==1||empty.parentNode!==null||content.childNodes.length!==2||content.firstChild!==a||content.lastChild!==b||a.data!=='A'||b.data!=='B')throw 'host ordinary children normalize independently';content.normalize();if(content.firstChild!==a||content.childNodes.length!==1||a.data!=='AB'||b.parentNode!==null||b.data!=='B'||ordinary.data!=='host')throw 'dedicated fragment normalization uses actual source';");
}

#[test]
fn shared_normalize_empty_removals_and_singleton_data_events_preserve_sequence_and_aliases(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var owner=new Document(),p=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),e=owner.createTextNode(''),a=owner.createTextNode('A'),mid=owner.createTextNode(''),b=owner.createTextNode('B'),last=owner.createTextNode(''),stop=owner.createComment('stop'),solo=owner.createTextNode('solo');for(var node of [e,a,mid,b,last,stop,solo])p.appendChild(node);var watch=new MutationObserver(function(){});watch.observe(p,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});p.normalize();var r=watch.takeRecords();if(r.length!==6||r[0].type!=='childList'||r[0].removedNodes[0]!==e||r[0].previousSibling!==null||r[0].nextSibling!==a||r[1].type!=='characterData'||r[1].target!==a||r[1].oldValue!=='A'||r[2].removedNodes[0]!==mid||r[2].previousSibling!==a||r[2].nextSibling!==b||r[3].removedNodes[0]!==b||r[3].previousSibling!==a||r[3].nextSibling!==last||r[4].removedNodes[0]!==last||r[4].previousSibling!==a||r[4].nextSibling!==stop||r[5].type!=='characterData'||r[5].target!==solo||r[5].oldValue!=='solo')throw 'sequential normalize records including leading/middle/end empties and singleton';if(a.data!=='AB'||b.data!=='B'||p.childNodes.length!==3||p.childNodes[0]!==a||p.childNodes[1]!==stop||p.childNodes[2]!==solo||e.parentNode!==null||mid.parentNode!==null||b.parentNode!==null||last.parentNode!==null)throw 'retained real normalized aliases';p.normalize();r=watch.takeRecords();if(r.length!==2||r[0].target!==a||r[0].oldValue!=='AB'||r[1].target!==solo||r[1].oldValue!=='solo')throw 'idempotent structure still native data events';");
}
#[test]
fn shared_normalize_captured_child_method_origin_precedes_native_walk(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Node.prototype.normalize,owner=new Document(),p=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),a=owner.createTextNode('A'),b=owner.createTextNode('B');p.appendChild(a);p.appendChild(b);if(saved.call(p)!==undefined||p.firstChild!==a||a.data!=='AB'||b.parentNode!==null)throw 'genuine captured shared normalize';var c=owner.createTextNode('C');p.appendChild(c);");page.set_location(&crate::navigation::address("https://other-shared-normalize.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(p);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(a.data!=='AB'||c.data!=='C'||p.childNodes.length!==2||c.parentNode!==p)throw 'origin before tree/data mutation';");
}
#[test]
fn shared_normalize_native_refusal_keeps_buffers_links_ranges_observers_and_recovers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var p=document.createElement('span'),a=document.createTextNode('left'),b=document.createTextNode('right');p.appendChild(a);p.appendChild(b);var list=p.childNodes,range=document.createRange();range.setStart(b,1);range.setEnd(b,4);var delivered=0,watch=new MutationObserver(function(){delivered++;});watch.observe(p,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});");let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);let limit=page.state.retained_limit;page.state.retained_limit=0;assert_eq!(page.console_eval(&mut doc,&mut forms,"p.normalize();").errors,1);assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);assert!(page.state.normalize_plan.is_none());page.state.retained_limit=limit;run(&mut doc,&mut forms,&mut page,"if(a.data!=='left'||b.data!=='right'||p.childNodes!==list||list.length!==2||b.parentNode!==p||range.startContainer!==b||range.endContainer!==b||range.startOffset!==1||range.endOffset!==4||watch.takeRecords().length||delivered)throw 'failed proposal no data/link/Range/observation prefix';p.normalize();var r=watch.takeRecords();if(a.data!=='leftright'||b.data!=='right'||p.firstChild!==a||list.length!==1||b.parentNode!==null||range.startContainer!==a||range.endContainer!==a||range.startOffset!==5||range.endOffset!==8||r.length!==2||r[0].type!=='characterData'||r[0].target!==a||r[0].oldValue!=='left'||r[1].removedNodes[0]!==b||delivered)throw 'fresh shared normalization recovery';");
}
